        Ayah(111, 2, "مَا أَغْنَىٰ عَنْهُ مَالُهُ وَمَا كَسَبَ", "কোন কাজে আসেনি তার ধন-সম্পদ ও যা কিছু সে উপার্জন করেছে।", "His wealth will not avail him or that which he gained.", "https://verses.quran.com/Alafasy/mp3/111002.mp3"),
        Ayah(111, 3, "سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ", "শীঘ্রই সে প্রবেশ করবে লেলিহান অগ্নিশিখায়,", "He will [enter to] burn in a Fire of [blazing] flame", "https://verses.quran.com/Alafasy/mp3/111003.mp3"),
        Ayah(111, 4, "وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ", "এবং তার স্ত্রীও, যে জ্বালানি কাঠ বহনকারিণী,", "And his wife [as well] - the carrier of firewood.", "https://verses.quran.com/Alafasy/mp3/111004.mp3"),
        Ayah(111, 5, "فِي جِيدِهَا حَبْلٌ مِّن مَّسَدٍ", "তার গলায় থাকবে পাকানো খেজুরের শক্ত রশি।", "Around her neck is a rope of [twisted] fiber.", "https://verses.quran.com/Alafasy/mp3/111005.mp3")
